mapper.select:
SELECT sm.minor_name AS catName, sasr.total_scene_count AS totalSceneCount FROM stat_app_scene_rpt sasr LEFT JOIN sys_app_scene_minor sm ON sasr.minor_code = sm.minor_code
AND sm.minor_code = #{query.minorCode}
AND sasr.region_code = #{query.regionCode}
GROUP BY sm.minor_name ORDER BY totalSceneCount DESC

SELECT coord_x AS coordX, coord_y AS coordY, count AS count FROM gc_biz_mng_comp_spatial -- 修正表名
AND minor_code = #{query.minorCode}
AND EXISTS ( SELECT 1 FROM biz_mng_comp_info bmci WHERE bmci.id = gc_biz_mng_comp_spatial.comp_id )
AND region_code = #{query.regionCode}
GROUP BY coord_x, coord_y

SELECT
normal_comp_count AS normalCompCount,
disabled_scene_count AS disabledSceneCount
FROM stat_app_scene_rpt


        AND minor_code = #{query.minorCode}


        AND region_code = #{query.regionCode}

SELECT c.comp_name AS compName, c.count FROM biz_mng_comp_info c
AND c.minor_code = #{query.minorCode}
AND c.region_code = #{query.regionCode}
ORDER BY c.hot_value DESC LIMIT 5
